// C documentation
//
//	// This computes the deviation of the principal inertia values without computing eigenvalues.
//	// It computes:
//	// ((I1 - I2)^2 + (I1 - I3)^2 + (I2 - I3)^2) / (I1^2 + I2^2 + I3^2)
//	// https://en.wikipedia.org/wiki/Cauchy_stress_tensor#Stress_deviator_tensor
func b3UpdateIsotropicInertia(tls *_Stack, world uintptr, body uintptr, bodySim uintptr) {
	var deviation, dx, dy, dz, mean, offDiagonal, tolerance float32
	var inertia Matrix3
	_, _, _, _, _, _, _, _ = deviation, dx, dy, dz, inertia, mean, offDiagonal, tolerance
	inertia = (*b3BodySim)(unsafe.Pointer(bodySim)).Inertia
	mean = (inertia.Cx.X + inertia.Cy.Y + inertia.Cz.Z) / float32FromFloat32(3)
	dx = inertia.Cx.X - mean
	dy = inertia.Cy.Y - mean
	dz = inertia.Cz.Z - mean
	offDiagonal = float32(inertia.Cy.X*inertia.Cy.X) + float32(inertia.Cz.X*inertia.Cz.X) + float32(inertia.Cz.Y*inertia.Cz.Y)
	// This is the square of the Frobenius matrix norm.
	// https://en.wikipedia.org/wiki/Matrix_norm
	deviation = float32(dx*dx) + float32(dy*dy) + float32(dz*dz) + float32(float32FromFloat32(2)*offDiagonal)
	tolerance = (*b3World)(unsafe.Pointer(world)).IsotropicInertiaTolerance
	if float32(float32FromFloat32(2)*deviation) > float32(float32(float32(float32(float32FromFloat32(3)*tolerance)*tolerance)*mean)*mean) {
		*(*uint32_t)(unsafe.Add(nil, body+80)) |= uint32(b3_enableGyroscopicTorque)
	} else {
		*(*uint32_t)(unsafe.Add(nil, body+80)) &= uint32FromInt32(^int32(b3_enableGyroscopicTorque))
	}
	b3SyncBodyFlags(tls, world, body)
}

func b3ShouldBodiesCollide(tls *_Stack, world uintptr, bodyA uintptr, bodyB uintptr) (r uint8) {
	var edgeIndex, jointId, jointKey, otherBodyId, otherEdgeIndex int32
	var joint uintptr
	var v1 bool
	_, _, _, _, _, _, _ = edgeIndex, joint, jointId, jointKey, otherBodyId, otherEdgeIndex, v1
	if (*b3Body)(unsafe.Pointer(bodyA)).Type1 != int32(b3_dynamicBody) && (*b3Body)(unsafe.Pointer(bodyB)).Type1 != int32(b3_dynamicBody) {
		return boolUint8(false1 != 0)
	}
	if (*b3Body)(unsafe.Pointer(bodyA)).JointCount < (*b3Body)(unsafe.Pointer(bodyB)).JointCount {
		jointKey = (*b3Body)(unsafe.Pointer(bodyA)).HeadJointKey
		otherBodyId = (*b3Body)(unsafe.Pointer(bodyB)).Id
	} else {
		jointKey = (*b3Body)(unsafe.Pointer(bodyB)).HeadJointKey
		otherBodyId = (*b3Body)(unsafe.Pointer(bodyA)).Id
	}
	for jointKey != -int32(1) {
		jointId = jointKey >> int32(1)
		edgeIndex = jointKey & int32(1)
		otherEdgeIndex = edgeIndex ^ int32(1)
		if v1 = !!(0 <= jointId && jointId < (*b3World)(unsafe.Pointer(world)).Joints.Count); !v1 {
			b3InternalAssert(tls, __ccgo_ts+1939, __ccgo_ts+494, int32FromInt32(2665))
		}
		_ = v1 || bool(int32FromInt32(0) != 0)
		joint = (*b3World)(unsafe.Pointer(world)).Joints.Data + uintptr(jointId)*72
		if int32FromUint8((*b3Joint)(unsafe.Pointer(joint)).CollideConnected) == false1 && (*(*b3JointEdge)(unsafe.Add(nil, joint+20+uintptr(otherEdgeIndex)*12))).BodyId == otherBodyId {
			return boolUint8(false1 != 0)
		}
		jointKey = (*(*b3JointEdge)(unsafe.Add(nil, joint+20+uintptr(edgeIndex)*12))).NextKey
	}
	return boolUint8(true1 != 0)
}

