// C documentation
//
//	// Gather the sibling pairs with a moved node. This is done serially, it is cache friendly.
func b3GatherMovedSiblings(tls *_Stack, tree uintptr, pairIndices uintptr) (r int32) {
	var count, nodeEnd, pair, v2 int32
	var nodes uintptr
	_, _, _, _, _ = count, nodeEnd, nodes, pair, v2
	nodes = (*b3DynamicTree)(unsafe.Pointer(tree)).Nodes
	nodeEnd = (*b3DynamicTree)(unsafe.Pointer(tree)).NodeEnd
	count = 0
	// Skip the root.
	pair = int32(2)
	for {
		if !(pair < nodeEnd) {
			break
		}
		// Push when either sibling moved.
		if ((*(*b3TreeNode)(unsafe.Add(nil, nodes+uintptr(pair)*32))).FlagIndex|(*(*b3TreeNode)(unsafe.Add(nil, nodes+uintptr(pair+int32(1))*32))).FlagIndex)&(uint32FromUint32(1)<<int32FromInt32(30)) != 0 {
			v2 = count
			count = count + 1
			*(*int32)(unsafe.Add(nil, pairIndices+uintptr(v2)*4)) = pair
		}
		goto _1
	_1:
		;
		pair = pair + int32(2)
	}
	return count
}

